create table if not exists public.cashbox(cashbox_id bigint generated always as identity primary key,cashbox_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),location_id bigint not null references public.locations(location_id),currency_id bigint not null references public.currencies(currency_id),account_id bigint not null references public.chart_accounts(account_id),unique(cashbox_name,subsidiary_id,location_id));
alter table public.cashbox enable row level security;
drop policy if exists "treasury_select" on public.cashbox;drop policy if exists "treasury_insert" on public.cashbox;drop policy if exists "treasury_update" on public.cashbox;drop policy if exists "treasury_delete" on public.cashbox;
create policy "treasury_select" on public.cashbox for select to authenticated using(true);create policy "treasury_insert" on public.cashbox for insert to authenticated with check(true);create policy "treasury_update" on public.cashbox for update to authenticated using(true) with check(true);create policy "treasury_delete" on public.cashbox for delete to authenticated using(true);
